stage_a_raw:
{
  "decisions": [
    {
      "decision": "period0_operational_linkage",
      "evidence": "\"The number of generators operational in a period cannot exceed the number operational in the previous period plus the number started in the current period.\"",
      "options": [
        "n[g,0] <= s[g,0] (no generators before period 0, so period-0 operational count is bounded by period-0 startups)",
        "no constraint linking n[g,0] to s[g,0] (period 0 treated as having no previous period, linkage only for t>=1)"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "no constraint linking n[g,0] to s[g,0] (period 0 treated as having no previous period, linkage only for t>=1)"
    },
    {
      "decision": "startup_variable_domain",
      "evidence": "\"All decision variables must be non-negative integers\"",
      "options": [
        "s[g,t] NonNegativeIntegers",
        "s[g,t] Binary"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "s[g,t] NonNegativeIntegers"
    },
    {
      "decision": "power_output_domain",
      "evidence": "\"power output must be non-negative\"",
      "options": [
        "p[g,t] NonNegativeReals",
        "p[g,t] NonNegativeIntegers"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "p[g,t] NonNegativeReals"
    },
    {
      "decision": "max_operational_constraint_placement",
      "evidence": "\"The number of operational generators cannot exceed 4 for Type 0 and 5 for Type 1 in any period.\"",
      "options": [
        "explicit constraint n[g,t] <= max_operational[g] for all g,t",
        "only via variable bounds on n[g,t] (no separate constraint row)"
      ],
      "plausibility": [
        0.5,
        0.5
      ],
      "majority_option": "explicit constraint n[g,t] <= max_operational[g] for all g,t"
    },
    {
      "decision": "reserve_capacity_definition",
      "evidence": "\"The total maximum output capacity of all generators in each period must be at least 115% of the demand for that period\"",
      "options": [
        "sum_g max_output[g]*n[g,t] >= 1.15*demand[t]",
        "sum_g p[g,t] >= 1.15*demand[t] (reserve on actual output)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "sum_g max_output[g]*n[g,t] >= 1.15*demand[t]"
    },
    {
      "decision": "startup_cost_charged_on_all_starts",
      "evidence": "\"startup costs of 347 units for Type 0 generators and 352 units for Type 1 generators when activated\"",
      "options": [
        "charge startup_cost[g]*s[g,t] for every start including period 0",
        "charge startup costs only for t>=1 (period-0 activations free)"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "charge startup_cost[g]*s[g,t] for every start including period 0"
    }
  ]
}
